corporate_design.toad_component_blueprint:
canvas {
  size: 900px 580px;
  fill: #1E293B;
  font-family: "Anton, sans-serif";
}

>orange = #FF5500;
>white = #FFFFFF;

rect #rescuePanel {
  at: center of canvas;
  size: 800px 480px;
  fill: #0F172A;
  stroke: >orange;
  stroke-width: 4px;
}

text #notrufNumber {
  at: top left of #rescuePanel offset 36px 36px;
  content: "NOTRUF 140 // BERGRETTUNG TIROL";
  font-size: 18px;
  font-weight: 900;
  color: >orange;
}

text #missionHeadline {
  at: below #notrufNumber offset 20px;
  content: "Einsatzbereit bei Sturm, Schnee & Steilwand";
  font-size: 36px;
  font-weight: 900;
  color: >white;
}
